const fs = require('fs');
const MOD = 1000000007n;

function modPow(base, exp) {
  let res = 1n;
  base %= MOD;
  while (exp > 0) {
    if (exp % 2 === 1) res = (res * base) % MOD;
    base = (base * base) % MOD;
    exp = Math.floor(exp / 2);
  }
  return res;
}

function ceilDiv(num, den) {
  if (num >= 0) return Math.floor((num + den - 1) / den);
  else return -Math.floor((-num) / den);
}

function applyAffine(a, b, rem, y_mod, inv_a_minus_1) {
  if (rem === 0) return y_mod;
  let a_pow = modPow(a, rem);
  let sum = (a_pow - 1n + MOD) % MOD;
  sum = (sum * inv_a_minus_1) % MOD;
  let b_term = (b * sum) % MOD;
  return (a_pow * y_mod + b_term) % MOD;
}

function main() {
  const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
  let ptr = 0;
  const N = input[ptr++];
  const M = input[ptr++];
  const K = input[ptr++];

  const a_spells = input.slice(ptr, ptr + N); ptr += N;
  const b_spells = input.slice(ptr, ptr + N); ptr += N;
  const a_meals = input.slice(ptr, ptr + M); ptr += M;
  const b_meals = input.slice(ptr, ptr + M); ptr += M;
  const Q = input[ptr++];
  const queries = input.slice(ptr, ptr + Q); ptr += Q;

  // Build meals and sort by descending b/(a-1), with a=1 => infinity
  let meals = [];
  for (let i = 0; i < M; i++) {
    meals.push([a_meals[i], b_meals[i]]);
  }
  meals.sort((m1, m2) => {
    let a1 = m1[0], b1 = m1[1];
    let a2 = m2[0], b2 = m2[1];
    if (a1 === 1 && a2 === 1) return 0;
    if (a1 === 1) return -1;
    if (a2 === 1) return 1;
    let left = BigInt(b1) * BigInt(a2 - 1);
    let right = BigInt(b2) * BigInt(a1 - 1);
    if (left > right) return -1;
    if (left < right) return 1;
    return 0;
  });

  let A_meal = 1n, B_meal = 0n;
  for (let [a, b] of meals) {
    let ba = BigInt(a);
    let bb = BigInt(b);
    B_meal = (ba * B_meal + bb) % MOD;
    A_meal = (ba * A_meal) % MOD;
  }

  // Build spell envelope
  let spellMap = new Map();
  for (let i = 0; i < N; i++) {
    let a = a_spells[i], b = b_spells[i];
    if (!spellMap.has(a) || b > spellMap.get(a)) {
      spellMap.set(a, b);
    }
  }
  let lines = [];
  for (let [a, b] of spellMap) {
    lines.push([a, b]);
  }
  lines.sort((x, y) => x[0] - y[0]);

  let stack = [];
  for (let [a, b] of lines) {
    if (stack.length === 0) {
      stack.push({a, b, start: -Infinity});
    } else {
      while (true) {
        let last = stack[stack.length - 1];
        let num = last.b - b;
        let den = a - last.a;
        let start = ceilDiv(num, den);
        if (stack.length >= 2) {
          if (start <= last.start) {
            stack.pop();
            continue;
          }
        }
        stack.push({a, b, start: start});
        break;
      }
    }
  }

  let maxLine = stack[stack.length - 1];
  let max_a = BigInt(maxLine.a);
  let max_b = BigInt(maxLine.b);
  let inv_max_a_minus_1 = 0n;
  if (max_a > 1n) {
    inv_max_a_minus_1 = modPow(max_a - 1n, Number(MOD - 2n));
  }

  function findLineIndex(y) {
    let lo = 0, hi = stack.length - 1;
    while (lo < hi) {
      let mid = Math.floor((lo + hi + 1) / 2);
      if (stack[mid].start <= y) lo = mid;
      else hi = mid - 1;
    }
    return lo;
  }

  let results = [];
  for (let qi = 0; qi < Q; qi++) {
    let x = queries[qi];
    let y = x;
    let y_mod = BigInt(x);
    let rem = K;

    while (rem > 0) {
      if (y > 1000000000) {
        y_mod = applyAffine(max_a, max_b, rem, y_mod, inv_max_a_minus_1);
        rem = 0;
        break;
      }
      let idx = findLineIndex(y);
      let line = stack[idx];
      let a = line.a;
      let b = line.b;
      if (a === 1) {
        let next_start = (idx + 1 < stack.length) ? stack[idx + 1].start : Infinity;
        if (next_start > 1000000000 || next_start === Infinity) {
          let add = BigInt(rem) * BigInt(b);
          y_mod = (y_mod + add) % MOD;
          rem = 0;
          break;
        } else {
          let R = next_start - 1;
          let steps_to_exceed = Math.floor((R - y) / b) + 1;
          if (rem < steps_to_exceed) {
            let add = BigInt(rem) * BigInt(b);
            y_mod = (y_mod + add) % MOD;
            rem = 0;
            break;
          } else {
            let add = BigInt(steps_to_exceed) * BigInt(b);
            y_mod = (y_mod + add) % MOD;
            y = y + steps_to_exceed * b;
            rem -= steps_to_exceed;
          }
        }
      } else {
        y_mod = (BigInt(a) * y_mod + BigInt(b)) % MOD;
        y = a * y + b;
        rem--;
      }
    }

    let ans = (A_meal * y_mod + B_meal) % MOD;
    results.push(ans.toString());
  }

  console.log(results.join('\n'));
}

main();
